INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('71b520da89a1d1cddf67','AMEDEX 2025 OBS (2).pdf','159','Obstetrics','A pregnant elementary school teacher, aged
24, presents to your GP office after she finds
that one of the students in her class has been
recently diagnosed with rubella by his GP; the
diagnosis, however, was not confirmed by
serologic studies. Her last vaccination against
rubella was when she was 12. Which one of
